CREATE TYPE "BusinessCategory" AS ENUM ('RETAIL','RESTAURANT','CLOTHING','ELECTRONICS','COSMETICS','SERVICES','ONLINE_SELLER','WHOLESALE','OTHER');
CREATE TYPE "Role" AS ENUM ('OWNER','ADMIN','MANAGER','CASHIER','VIEWER');
CREATE TYPE "CustomerStatus" AS ENUM ('NEW','ACTIVE','RETURNING','INACTIVE','HIGH_VALUE');
CREATE TYPE "OrderStatus" AS ENUM ('DRAFT','PENDING_PAYMENT','PARTIALLY_PAID','PAID','PROCESSING','SHIPPED','DELIVERED','CANCELLED','REFUNDED','DISPUTED');
CREATE TABLE "Business" ("id" TEXT PRIMARY KEY,"businessName" TEXT NOT NULL,"ownerName" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"phone" TEXT NOT NULL,"businessCategory" "BusinessCategory" NOT NULL,"location" TEXT,"currency" TEXT NOT NULL DEFAULT 'KES',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'VIEWER',"businessId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT);
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT,"email" TEXT,"address" TEXT,"notes" TEXT,"status" "CustomerStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Customer_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"name" TEXT NOT NULL,"sku" TEXT NOT NULL,"category" TEXT,"description" TEXT,"sellingPrice" INTEGER NOT NULL,"costPrice" INTEGER NOT NULL,"stockQuantity" INTEGER NOT NULL DEFAULT 0,"reorderLevel" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,UNIQUE("businessId","sku"));
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"orderNumber" TEXT NOT NULL UNIQUE,"businessId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'DRAFT',"subtotal" INTEGER NOT NULL,"discount" INTEGER NOT NULL DEFAULT 0,"tax" INTEGER NOT NULL DEFAULT 0,"total" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'KES',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT);
CREATE TABLE "OrderItem" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitPrice" INTEGER NOT NULL,"total" INTEGER NOT NULL,CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE,CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"oldValue" JSONB,"newValue" JSONB,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE INDEX "Customer_businessId_name_idx" ON "Customer"("businessId","name"); CREATE INDEX "Product_businessId_name_idx" ON "Product"("businessId","name"); CREATE INDEX "Order_businessId_status_createdAt_idx" ON "Order"("businessId","status","createdAt"); CREATE INDEX "AuditLog_businessId_createdAt_idx" ON "AuditLog"("businessId","createdAt");
